from rules import SOLVERS


def solve(data):
    return {component_id: solver(data[component_id])
            for component_id, solver in SOLVERS.items()}

def _rounded(numerator, mode):
    denominator = 10000
    if mode == "half_up":
        return (numerator + denominator // 2) // denominator
    return numerator // denominator


def _ledger(data, sequence_first, discounted_tax, refunds):
    cutoff = data.get("cutoff", 10**9)
    chosen = {}
    for position, event in enumerate(data["events"]):
        sequence = event.get("sequence", 0)
        if sequence > cutoff:
            continue
        event_id = event.get("id", "anonymous:" + str(position))
        if sequence_first:
            key = (sequence, event.get("revision", 0), position)
        else:
            key = (event.get("revision", 0), position)
        if event_id not in chosen or key > chosen[event_id][0]:
            chosen[event_id] = (key, event)

    balances = dict(data.get("opening", {}))
    mode = data["rounding"]
    for _, event in chosen.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = _rounded(raw * (10000 - discount), mode)
        base = net if discounted_tax else raw
        tax = _rounded(base * event.get("tax_bp", 0), mode)
        total = net + tax
        if refunds and event.get("kind") == "refund":
            total = -total
        key = event.get("account", "default") + "|" + event.get("currency", "USD")
        balances[key] = balances.get(key, 0) + total
    return {"balances": balances}


def _component_01(data):
    return _ledger(data, True, True, True)


def _component_02(data):
    return _ledger(data, False, False, True)


def _component_03(data):
    return _ledger(data, True, False, True)


def _component_04(data):
    return _ledger(data, False, True, True)


def _component_05(data):
    return _ledger(data, True, True, True)


def _component_06(data):
    packages = data["packages"]
    features = set(data.get("features", []))
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    names = sorted(packages)
    best_vector = None
    best_install = None

    def acyclic(edges):
        active = set()
        done = set()

        def visit(name):
            if name in active:
                return False
            if name in done:
                return True
            active.add(name)
            for other in edges.get(name, []):
                if not visit(other):
                    return False
            active.remove(name)
            done.add(name)
            return True

        return all(visit(name) for name in edges)

    def search(assigned, constraints):
        nonlocal best_vector, best_install
        for name, row in assigned.items():
            version = row["version"]
            if any(not low <= version <= high
                   for low, high in constraints.get(name, [])):
                return

        unresolved = sorted(set(constraints) - set(assigned))
        if not unresolved:
            edges = {}
            for name, row in assigned.items():
                edges[name] = [dep["name"] for dep in row.get("deps", [])
                               if not dep.get("feature", "") or
                               dep.get("feature") in features]
            if not acyclic(edges):
                return
            vector = tuple(assigned[name]["version"] if name in assigned else -1
                           for name in names)
            if best_vector is None or vector < best_vector:
                best_vector = vector
                best_install = {name: row["version"]
                                for name, row in assigned.items()}
            return

        name = unresolved[0]
        ranges = constraints[name]
        rows = sorted(packages.get(name, []), key=lambda row: row["version"])
        for row in rows:
            version = row["version"]
            if any(not low <= version <= high for low, high in ranges):
                continue
            if version in blocked.get(name, []):
                continue
            if name in pins and version != pins[name]:
                continue
            next_assigned = dict(assigned)
            next_assigned[name] = row
            next_constraints = {key: list(value)
                                for key, value in constraints.items()}
            for dep in row.get("deps", []):
                feature = dep.get("feature", "")
                if feature and feature not in features:
                    continue
                next_constraints.setdefault(dep["name"], []).append(
                    (dep["min"], dep["max"]))
            search(next_assigned, next_constraints)

    roots = {name: [tuple(bounds)] for name, bounds in data["roots"].items()}
    search({}, roots)
    if best_install is None:
        return {"error": "unsatisfiable"}
    return {"versions": best_install}


def _component_07(data):
    from itertools import combinations

    jobs = data["jobs"]
    k = data["k"]
    blocked = set(data.get("blocked", []))
    mandatory = set(data.get("mandatory", []))
    quotas = data.get("quotas", {})
    if mandatory & blocked:
        return {"error": "impossible"}

    options = [job for job in jobs if job["id"] not in blocked]
    best_ids = None
    best_value = None
    for subset in combinations(options, k):
        ids = {job["id"] for job in subset}
        if not mandatory.issubset(ids):
            continue
        counts = {}
        for job in subset:
            counts[job["group"]] = counts.get(job["group"], 0) + 1
        if any(not low <= counts.get(group, 0) <= high
               for group, (low, high) in quotas.items()):
            continue
        intervals = sorted((job["start"], job["end"]) for job in subset)
        if any(intervals[i][0] < intervals[i - 1][1]
               for i in range(1, len(intervals))):
            continue
        selected = tuple(sorted(ids))
        value = sum(job["value"] for job in subset)
        if (best_value is None or value > best_value or
                (value == best_value and selected < best_ids)):
            best_value, best_ids = value, selected

    if best_ids is None:
        return {"error": "impossible"}
    return {"selected": list(best_ids), "value": best_value}


def _component_08(data):
    import heapq

    required = data.get("required", [])
    bit = {node: 1 << index for index, node in enumerate(required)}
    full = (1 << len(required)) - 1
    initial_mask = bit.get(data["source"], 0)
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)

    start_state = (data["source"], data["coupons"], initial_mask)
    distances = {start_state: data["start"]}
    queue = [(data["start"], data["source"], data["coupons"], initial_mask)]
    while queue:
        arrival, node, remaining, mask = heapq.heappop(queue)
        state = (node, remaining, mask)
        if distances.get(state) != arrival:
            continue
        if node == data["target"] and remaining == 0 and mask == full:
            return {"arrival": arrival}
        for edge in graph[node]:
            depart = max(arrival, edge["open"])
            if depart >= edge["close"]:
                continue
            choices = [(edge["duration"], remaining)]
            if remaining:
                duration = max(2, edge["duration"] - edge.get("discount", 0))
                choices.append((duration, remaining - 1))
            next_mask = mask | bit.get(edge["v"], 0)
            for duration, next_remaining in choices:
                next_arrival = depart + duration
                if next_arrival > data["deadline"]:
                    continue
                next_state = (edge["v"], next_remaining, next_mask)
                if next_arrival < distances.get(next_state, float("inf")):
                    distances[next_state] = next_arrival
                    heapq.heappush(queue, (next_arrival, edge["v"],
                                           next_remaining, next_mask))
    return {"arrival": None}


